head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF30601";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — itemSearch, threePerson

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_itemSearch", fn: function(){ return (!(String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "tr_165", fn: function(){ return (!(String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "tr_177", fn: function(){ return (!(String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "tr_188", fn: function(){ return (!(String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "tr_200", fn: function(){ return (!(String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "if_itemSearch_2", fn: function(){ return ((String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "tr_212", fn: function(){ return ((String(((dma_pageContext.get("itemSearch") ?? "")) == null ? '' : ((dma_pageContext.get("itemSearch") ?? ""))).length === 0)); } }, { id: "if_threePerson", fn: function(){ return (!(String(((dma_pageContext.get("threePerson") ?? "")) == null ? '' : ((dma_pageContext.get("threePerson") ?? ""))).length === 0)); } }, { id: "tr_259", fn: function(){ return (!(String(((dma_pageContext.get("threePerson") ?? "")) == null ? '' : ((dma_pageContext.get("threePerson") ?? ""))).length === 0)); } }, { id: "tr_269", fn: function(){ return (!(String(((dma_pageContext.get("threePerson") ?? "")) == null ? '' : ((dma_pageContext.get("threePerson") ?? ""))).length === 0)); } }, { id: "if_threePerson_2", fn: function(){ return ((String(((dma_pageContext.get("threePerson") ?? "")) == null ? '' : ((dma_pageContext.get("threePerson") ?? ""))).length === 0)); } }, { id: "tr_275", fn: function(){ return ((String(((dma_pageContext.get("threePerson") ?? "")) == null ? '' : ((dma_pageContext.get("threePerson") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_beforeName", fn: function () { return String((dma_pageContext.get("beforeName") ?? "")); } },
        { childId: "ipt_comCode", fn: function () { return String((dma_pageContext.get("comCode") ?? "")); } },
        { childId: "ipt_comName", fn: function () { return String((dma_pageContext.get("comName") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } },
        { childId: "btn_historyChgName", fn: function () { return String(dma_itemInfo.get("cpnmChgCnt")) + String((dma_pageContext.get("comNm") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const id = $c.util.getComponent("id_news");
    if ($c.util.getComponent('dma_submitReq').get('newsScrollY') !== '') {
        document.body.scrollTop = $c.util.getComponent('dma_submitReq').get('newsScrollY');
    }
    if ('null' === 'end') {

    }
    if ('null' === '' && 'null' === '' && 'null' === '') {
        $c.util.getComponent("ipt_check1").setValue(true);
        $c.util.getComponent("ipt_check2").setValue(true);
        $c.util.getComponent("ipt_check3").setValue(true);
    }
    if ('null' === '' && 'null' === '') {
        setPeriod('12');
    }
    if ($c.util.getComponent("dma_submitReq").get("beforeName") !== '') {
        self.before.innerHTML = $c.util.getComponent("dma_submitReq").get("beforeName");
    }
};

/**
 * @method
 * @name initField
 * @description init Field 처리
 * @returns {void}
 * @hidden N
 */
scwin.initField = function () {
    $c.util.getComponent('dma_submitReq').set('name', "");
    $c.util.getComponent('dma_submitReq').set('birthday', "");
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30601.onpageload' });
    }
};

