///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name findPosY
 * @description find Pos Y 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.findPosY = function (obj) {
    let curtop = 0;
    if (obj.offsetParent) {
        while (obj.offsetParent) {
            curtop += obj.offsetTop;
            obj = obj.offsetParent;
        }
    } else {
        if (obj.y) {
            curtop += obj.y;
        }
    }
    return curtop;
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} mode mode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (mode) {
    $c.util.getComponent('dma_submitReq').set('method', "itemSearchList");
    $c.util.getComponent('dma_submitReq').set('SCREN_PROCES_TP_CD', "01");
    if ((String($c.util.getComponent('ipt_check1').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind1", "00");
    }
